void main() {
  // exact regex from test/ci_2408_rosetta_interpreter_guard_test.dart
  final re = RegExp(r'^\s*arch -x86_64 (\S+)');
  const script = '# gh-1522: comment\nversion="1"\narch -x86_64 dart build cli --target=bin/fa.dart\n';
  print('hasMatch(multi-line script, first line is comment): ${re.hasMatch(script)}');
  print('allMatches count: ${re.allMatches(script).length}');
  print('hasMatch(script starting with arch): ${re.hasMatch('arch -x86_64 dart build cli')}');
  // per-line matching (AC1 does this correctly)
  final perLine = script.split('\n').where((l) => !l.trim().startsWith('#')).toList();
  print('per-line hits: ${[for (final l in perLine) if (re.firstMatch(l.trimLeft()) != null) l.trim()]}');
}
EOF
cd /tmp/probe2408 && dart run anchor.dart

